/** Provider-owned signature fields must be regenerated by /oauth2/authorize. */
export function restartOAuthPath(search: string) {
  const params = new URLSearchParams(search);
  if (!params.get("client_id")) return null;
  for (const key of ["sig", "exp", "ba_iat", "ba_param", "ba_pl"]) params.delete(key);
  return `/api/auth/oauth2/authorize?${params.toString()}`;
}

export function oauthRequestExpired(search: string, now = Date.now()) {
  const params = new URLSearchParams(search);
  if (!params.has("sig") || !params.has("exp")) return false;
  const expires = Number(params.get("exp"));
  return !Number.isFinite(expires) || expires * 1000 <= now;
}

export function isInvalidOAuthQuery(error: unknown) {
  if (!error || typeof error !== "object") return false;
  const details = error as { error?: unknown; code?: unknown; message?: unknown };
  return [details.error, details.code, details.message].some(
    (value) => value === "invalid_signature" || value === "INVALID_SIGNATURE",
  );
}

export function authErrorMessage(error: unknown, fallback: string) {
  if (isInvalidOAuthQuery(error))
    return "La demande de connexion a expiré ou n’est plus valide. Reprenez la connexion pour continuer.";
  if (error && typeof error === "object") {
    const details = error as {
      message?: unknown;
      error_description?: unknown;
      status?: unknown;
    };
    if (details.status === 429)
      return "Trop de tentatives. Patientez avant de réessayer.";
    for (const detail of [details.message, details.error_description]) {
      if (typeof detail === "string" && detail.trim()) return detail;
    }
  }
  return fallback;
}
